// SPDX-License-Identifier: MIT
pragma solidity >=0.4.22 <0.9.0;

contract PaymentTransactionStorage {
    // Struktur data untuk menyimpan informasi transaksi
    struct Transaction {
        string order_id;
        uint256 amount;
        string status;
        string currency;
        string payment_method;
        string payment_email;
        string merchant_name;
        string customer_name;
        uint256 timestamp;
    }

    // Mapping untuk menyimpan transaksi berdasarkan order_id
    mapping(string => Transaction) public transactions;

    // Array untuk menyimpan daftar order_id yang sudah digunakan
    string[] public orderIds;

    // Event untuk mencatat transaksi baru
    event TransactionStored(
        string order_id,
        uint256 amount,
        string status,
        string currency,
        string payment_method,
        string payment_email,
        string merchant_name,
        string customer_name,
        uint256 timestamp
    );

    // Modifier untuk memeriksa apakah order_id sudah ada
    modifier isUniqueOrderId(string memory order_id) {
        require(!isOrderIdExists(order_id), "Order ID already exists");
        _;
    }

    // Fungsi untuk menyimpan transaksi dengan validasi order_id unik
    function storeTransaction(
        string memory order_id,
        uint256 amount,
        string memory status,
        string memory currency,
        string memory payment_method,
        string memory payment_email,
        string memory merchant_name,
        string memory customer_name
    ) public isUniqueOrderId(order_id) {
        // Membuat transaksi baru dan menyimpannya
        transactions[order_id] = Transaction({
            order_id: order_id,
            amount: amount,
            status: status,
            currency: currency,
            payment_method: payment_method,
            payment_email: payment_email,
            merchant_name: merchant_name,
            customer_name: customer_name,
            timestamp: block.timestamp
        });

        // Menambahkan order_id ke daftar
        orderIds.push(order_id);

        // Emit event untuk mencatat transaksi yang disimpan
        emit TransactionStored(
            order_id,
            amount,
            status,
            currency,
            payment_method,
            payment_email,
            merchant_name,
            customer_name,
            block.timestamp
        );
    }

    // Fungsi untuk mendapatkan informasi transaksi berdasarkan order_id
    function getTransaction(string memory order_id) public view returns (
        string memory,
        uint256,
        string memory,
        string memory,
        string memory,
        string memory,
        string memory,
        string memory,
        uint256
    ) {
        Transaction memory t = transactions[order_id];
        return (
            t.order_id,
            t.amount,
            t.status,
            t.currency,
            t.payment_method,
            t.payment_email,
            t.merchant_name,
            t.customer_name,
            t.timestamp
        );
    }

    // Fungsi untuk memeriksa apakah order_id sudah ada
    function isOrderIdExists(string memory order_id) public view returns (bool) {
        return bytes(transactions[order_id].order_id).length > 0;
    }

    // Fungsi untuk mendapatkan total jumlah transaksi yang disimpan
    function getTransactionCount() public view returns (uint256) {
        return orderIds.length;
    }

    // Fungsi untuk mendapatkan semua order_id yang disimpan
    function getAllOrderIds() public view returns (string[] memory) {
        return orderIds;
    }

    // Fungsi untuk mendapatkan semua data transaksi yang disimpan
    function getAllTransactions() public view returns (Transaction[] memory) {
        Transaction[] memory allTransactions = new Transaction[](orderIds.length);
        
        for (uint256 i = 0; i < orderIds.length; i++) {
            allTransactions[i] = transactions[orderIds[i]];
        }
        
        return allTransactions;
    }
}
